def classifier_triangle(a, b, c):
    # 1. Vérification positivité
    if a <= 0 or b <= 0 or c <= 0:
        return "Impossible"

    # 2. Tri des côtés
    cotes = [a, b, c]
    cotes.sort()  # cotes[0] <= cotes[1] <= cotes[2]
    x, y, z = cotes[0], cotes[1], cotes[2]

    # 3. Inégalité triangulaire
    if x + y <= z:
        return "Impossible"

    # 4. Classification par Pythagore
    if x**2 + y**2 == z**2:
        return "Rectangle"
    elif x**2 + y**2 > z**2:
        return "Acutangle"
    else:
        return "Obtusangle"
